test('defense scores, manual links and all formulas survive refresh and JSON export', async ({ page }) => {
    await mockAttackData(page, [...objects, {...M0000, id:'course-of-action-unmapped', name:'Unrelated defense', external_references:[{external_id:'M9999'}]}]);
    await page.addInitScript(() => localStorage.setItem('attackwise-language','en'));
    await page.goto('/');
    await page.getByRole('button',{name:/T1595 Active Scanning/}).click();
    await page.locator('#scenario-score').fill('8');
    await page.getByRole('button',{name:'Save score',exact:true}).click();
    const nav = page.getByRole('navigation',{name:'Plan views'});
    await nav.getByRole('button',{name:/Defensive Plan/}).click();
    const official = page.locator('.mitigation').filter({hasText:'Network Defense'});
    await official.getByRole('button',{name:'Select defense',exact:true}).click();
    await page.locator('#scenario-score').fill('9');
    await page.getByRole('button',{name:'Save score',exact:true}).click();
    await expect(official).toHaveAttribute('data-defense','high');
    const manual = page.locator('.mitigation').filter({hasText:'Unrelated defense'});
    await manual.getByRole('button',{name:'Select defense',exact:true}).click();
    await page.locator('.defense-links input[type=checkbox]').check();
    await page.locator('#scenario-score').fill('3');
    await page.getByRole('button',{name:'Save score',exact:true}).click();
    await expect(manual).toHaveAttribute('data-defense','low');
    await expect(manual).toContainText('User-defined mapping');
    await nav.getByRole('button',{name:/Final Plan/}).click();
    for (const [formula, defense, result, index] of [['strongest','9','-1','0'],['average','6','2','20'],['sum','12','-4','0']]) {
        await page.getByLabel('Risk formula',{exact:true}).selectOption(formula);
        await expect(page.locator('.combined-defense')).toHaveText(defense);
        await expect(page.locator('.formula-result')).toHaveText(result);
        await expect(page.locator('.gauge > div > strong')).toHaveText(index);
    }
    await page.reload();
    await page.locator('.wise-saved-plans .saved-plan-open').first().click();
    await nav.getByRole('button',{name:/Final Plan/}).click();
    await expect(page.getByLabel('Risk formula',{exact:true})).toHaveValue('sum');
    await expect(page.locator('.formula-result')).toHaveText('-4');
    const downloaded = page.waitForEvent('download');
    await page.getByRole('button',{name:'Download plan JSON',exact:true}).click();
    await page.locator('#uploader').setInputFiles((await (await downloaded).path())!);
    await nav.getByRole('button',{name:/Final Plan/}).click();
    await expect(page.locator('.formula-result')).toHaveText('-4');
    await page.locator('.report-table summary').click();
    await page.locator('.report-table').getByRole('button',{name:/9\/10/}).click();
    await page.getByRole('button',{name:'Clear score',exact:true}).click();
    await expect(page.locator('.formula-result')).toHaveText('Not Rated');
    await page.getByRole('button',{name:'Close scoring panel'}).click();
    await nav.getByRole('button',{name:/Attack Plan/}).click();
    await page.getByRole('button',{name:'Clear',exact:true}).click();
    await page.getByRole('button',{name:/T1595 Active Scanning/}).click();
    await page.getByRole('button',{name:'Skip for now',exact:true}).click();
    await nav.getByRole('button',{name:/Defensive Plan/}).click();
    await expect(page.locator('.attack-list .status[data-status=covered]')).toHaveCount(0);
    await expect(page.locator('.mitigation.chosen')).toHaveCount(0);
});
